// lb_balance.cpp - apply a bundled balance patch to the in-RAM blueprints.
//
// Part of legobattles-decomp. Not an upstream ndsrecomp file; see
// port/runner/README.md.
//
// The three community balance mods change BP/Entities.ebp and nothing else
// (docs/101), so a balance patch is a list of changed bytes. Those lists are
// generated by tools/lb_genbalance.py and compiled in; the mods' authors are
// credited in lb_balance_data.h and docs/101.
//
// WHY DELTAS AND NOT THE WHOLE FILE
//
// The first version of this loaded a mod's Entities.ebp, decompressed it, and
// wrote its bytes over the in-RAM block. That worked mechanically and was
// WRONG. Comparing the decompressed file against RAM showed 35,598 differing
// bytes where the bundled vanilla-to-mod diff is only 835: the loader fixes up
// far more than the two string fields at +0x00 and +0x24, and writing the file
// wholesale would have clobbered every one of those fixups.
//
// Applying only the vanilla-to-mod DELTA touches 835 bytes that are genuinely
// balance values and leaves every loader-owned byte exactly as the game left
// it. Same result, none of the collateral.

#include "lb_overlay.h"
#include "lb_balance_data.h"

#include <algorithm>
#include <cstddef>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <string>
#include <vector>

extern "C" {
#include "runtime_arm.h"
}

namespace {

constexpr int kTableCount =
    (int)(sizeof(lb_balance_tables) / sizeof(lb_balance_tables[0]));

int g_applied_slot = 0;    // 0 vanilla, else the dropdown index

// docs/386: TAKING A PACK BACK OUT. The deltas hold only the pack's bytes, so
// there was no undo, and a change needed a restart. Now every byte any pack
// touches is kept as the game loaded it, in the runs' own order, before any
// pack is applied (lb_balance_snapshot, at the blueprints' discovery), and
// lb_balance_revert writes the applied pack's bytes back from it.
std::vector<std::vector<uint8_t>> g_vanilla;
unsigned int g_snap_base = 0u;

}  // namespace

// docs/386: one past the furthest byte any pack touches, from the block's
// base -- how much of the block has to hold still before it is used.
extern "C" unsigned int lb_balance_extent(void) {
    unsigned int end = 0u;
    for (int t = 0; t < kTableCount; ++t) {
        const LbBalanceTable& table = lb_balance_tables[t];
        for (uint32_t i = 0; i < table.run_count; ++i) {
            const unsigned int e = table.runs[i].offset + table.runs[i].length;
            if (e > end) end = e;
        }
    }
    return end;
}

extern "C" void lb_balance_snapshot(unsigned int blueprint_base) {
    g_vanilla.assign((size_t)kTableCount, std::vector<uint8_t>());
    for (int t = 0; t < kTableCount; ++t) {
        const LbBalanceTable& table = lb_balance_tables[t];
        std::vector<uint8_t>& v = g_vanilla[(size_t)t];
        v.reserve(table.byte_count);
        for (uint32_t i = 0; i < table.run_count; ++i) {
            const LbBalanceRun& run = table.runs[i];
            for (uint32_t j = 0; j < run.length; ++j)
                v.push_back(bus_read_u8(blueprint_base + run.offset + j));
        }
    }
    g_snap_base = blueprint_base;
}

// 1 when no pack is left applied; 0 when this one cannot be taken out (no
// snapshot of this block).
extern "C" int lb_balance_revert(unsigned int blueprint_base) {
    const int slot = g_applied_slot;
    if (slot <= 0) return 1;
    if (blueprint_base != g_snap_base || slot > (int)g_vanilla.size()) return 0;
    const LbBalanceTable& table = lb_balance_tables[slot - 1];
    const std::vector<uint8_t>& v = g_vanilla[(size_t)(slot - 1)];
    uint32_t k = 0, written = 0;
    for (uint32_t i = 0; i < table.run_count; ++i) {
        const LbBalanceRun& run = table.runs[i];
        for (uint32_t j = 0; j < run.length; ++j, ++k) {
            if (k >= v.size()) return 0;
            const uint32_t addr = blueprint_base + run.offset + j;
            if (bus_read_u8(addr) != v[k]) {
                bus_write_u8(addr, v[k]);
                ++written;
            }
        }
    }
    g_applied_slot = 0;
    std::fprintf(stderr, "[lb_balance] %s taken out: %u bytes back to the "
                 "loaded values\n", table.name, written);
    return 1;
}

// slot: 1 Rebalance, 2 FactionWars, 3 Funlite, 4 FunLite2. Slot 0 is vanilla and does
// nothing; lb_balance_revert takes a pack back out (docs/386).
extern "C" int lb_balance_apply(int slot, unsigned int blueprint_base,
                                char* error, int error_size) {
    auto fail = [&](const char* why) {
        if (error && error_size > 0) std::snprintf(error, (size_t)error_size, "%s", why);
        return 0;
    };
    if (slot <= 0 || slot > kTableCount) return fail("no such balance patch");
    if (blueprint_base == 0u) return fail("blueprints not in RAM yet");

    const LbBalanceTable& table = lb_balance_tables[slot - 1];
    uint32_t written = 0;
    for (uint32_t i = 0; i < table.run_count; ++i) {
        const LbBalanceRun& run = table.runs[i];
        for (uint32_t j = 0; j < run.length; ++j) {
            const uint32_t addr = blueprint_base + run.offset + j;
            if (bus_read_u8(addr) != run.bytes[j]) {
                bus_write_u8(addr, run.bytes[j]);
                ++written;
            }
        }
    }

    g_applied_slot = slot;
    // "%u of %u bytes written" READ AS A FAILURE and it was not one. The loop
    // above writes only where the current byte DIFFERS, so this counter is the
    // number of bytes CHANGED -- the remainder are bytes the pack and vanilla
    // already agree on, which need no write. Reporting both numbers so nobody
    // else reads a shortfall into it; a genuine failure would show as a byte
    // that differs and stays differing, which is a different check entirely.
    std::fprintf(stderr,
                 "[lb_balance] %s applied: %u runs, %u of %u bytes changed "
                 "(%u already matched vanilla)\n",
                 table.name, table.run_count, written, table.byte_count,
                 table.byte_count - written);
    return 1;
}

extern "C" int lb_balance_is_applied(void) { return g_applied_slot != 0 ? 1 : 0; }
// docs/396: a game reset reloads the vanilla blueprints, so no pack is
// applied any more; the patcher applies the chosen one again once they settle.
extern "C" void lb_balance_custom_on_reset(void);   // docs/404, below
extern "C" void lb_balance_on_reset(void) {
    g_applied_slot = 0;
    lb_balance_custom_on_reset();
}
extern "C" int lb_balance_applied_slot(void) { return g_applied_slot; }

extern "C" int lb_balance_pack_count(void) { return kTableCount; }

extern "C" const char* lb_balance_name(int slot) {
    if (slot <= 0 || slot > kTableCount) return "Off (Vanilla)";
    return lb_balance_tables[slot - 1].name;
}

extern "C" int lb_balance_byte_count(int slot) {
    if (slot <= 0 || slot > kTableCount) return 0;
    return (int)lb_balance_tables[slot - 1].byte_count;
}

// ── docs/404: THE PLAYER'S OWN VALUES, FIELD BY FIELD ──────────────────────
//
// A third layer over the blueprints, after the pack and Same-builders: a set
// of (record, field) -> value the Balance tab edits. Writing it keeps the
// bytes it replaced, so it comes out exactly; the patcher (lb_patches.cpp)
// takes it out before it touches the pack or the builders and puts it back
// after, so each layer sits on the one below.
//
// THE RECORDS, from tools/lb_blueprints.py's walk of Entities.ebp: 182 unit
// and building records of 0x7C bytes (type 0) from offset 4, then 27
// projectiles of 0x74 (type 1). The fields are the ones docs/20-29 traced to
// the code that reads them:
//   cost +0x5E u16, build time +0x60 u16, health +0x62 u16, mana +0x64 u16,
//   speed +0x0C u32 (20.12 tiles per tick; 0xFFFFFFFF for a structure),
//   melee damage +0x68 u8 and its spread +0x6A u8, attack interval +0x6D u8
//   (1/30 s ticks), attack range +0x6F u8, resource yield +0x6C u8;
//   a projectile's hit damage at +0x6C/+0x6E and its impact damage at
//   +0x70/+0x72, u16 each (docs/408: not one range written twice, as this
//   once said -- two the game reads apart, equal in the vanilla data), its
//   speed at +0x0C and its flags at +0x5E..+0x6B (kAttackFields).
//
// IN A BATTLE, OFFLINE: allowed, and recorded. A unit reads its blueprint as
// it acts, so a change applies from that moment; a recording carries the set
// in its header (`balc=`) and every change as a `b` line on its frame, so a
// replay changes on the same frame. ONLINE: refused -- both machines must
// run one rule set (the lockstep), and nothing carries a set across yet.
namespace {

struct BalField {
    const char* name;
    uint16_t off;
    uint8_t width;
    uint16_t mirror;   // a second copy written alongside (projectiles), or 0
    int max;
};
const BalField kUnitFields[] = {
    {"Cost", 0x5E, 2, 0, 65535},
    {"Build time", 0x60, 2, 0, 65535},
    {"Health", 0x62, 2, 0, 65535},
    {"Mana", 0x64, 2, 0, 65535},
    {"Speed", 0x0C, 4, 0, 0x7FFFFFFF},
    {"Melee damage", 0x68, 2, 0, 65535},   // docs/426: u16 (+0x69 is its high byte)
    {"Melee spread", 0x6A, 2, 0, 65535},   // u16 (+0x6B)
    {"Attack interval", 0x6D, 1, 0, 255},
    {"Attack range", 0x6F, 1, 0, 255},
    {"Resource yield", 0x6C, 1, 0, 255},
    // docs/408: a hero's five spell slots, spell ids 1..0x22 and 0 empty
    // (docs/106: the factory FUN_0207BC0C bounds the id at 0x22). Shown in
    // their own Heroes section, not as columns (LB_BAL_SPELL_FIELD0).
    {"Spell 1", 0x72, 1, 0, 0x22},
    {"Spell 2", 0x73, 1, 0, 0x22},
    {"Spell 3", 0x74, 1, 0, 0x22},
    {"Spell 4", 0x75, 1, 0, 0x22},
    {"Spell 5", 0x76, 1, 0, 0x22},
    // docs/426: the Entities Editor's other unit fields, APPENDED so a stored
    // balance_custom index keeps its meaning (LB_BAL_TRAIT_FIELD0 = 15). Readers:
    //   +0x16/+0x17/+0x18/+0x1A: FUN_0205079C (0x0205079C) tests them in that
    //     order on the blueprint at [entity+0xE0]+4; +0x1B in the same function;
    //   +0x19 Trees: FUN_02001510 (0x02001510), a blueprint-byte getter;
    //   +0x1D Hitbox size: FUN_02001170 (0x02001170) indexes its size table;
    //   +0x66 Projectile: FUN_0205079C reads the u16 and tests it in a
    //     projectile-id range (also FUN_02050F3C, FUN_02053F90);
    //   +0x70 AI priority and +0x71 Defogged area: docs/25 (FUN_020638C8
    //     accumulates +0x70; Sim::HarvestEngineer reads +0x71);
    //   +0x21 Uninteractable: UNCONFIRMED -- FUN_020E8964 reads a +0x21 off a
    //     [obj+4] record whose struct was not traced to the blueprint.
    {"Land", 0x17, 1, 0, 1},
    {"Water", 0x18, 1, 0, 1},
    {"Trees", 0x19, 1, 0, 1},
    {"Building collision", 0x1A, 1, 0, 1},
    {"Land<->water", 0x1B, 1, 0, 1},
    {"Hitbox size", 0x1D, 1, 0, 255},
    {"Uninteractable", 0x21, 1, 0, 1},
    {"Projectile", 0x66, 2, 0, 65535},
    {"AI priority", 0x70, 1, 0, 255},
    {"Defogged area", 0x71, 1, 0, 255},
    {"Not water-only", 0x16, 1, 0, 1},   // the editor's BoatAntiFlag: 0 for a water-only unit
};
// docs/408: +0x70/+0x72 are NOT a copy of +0x6C/+0x6E. The hit (FUN_0206E408,
// `ldrh [bp,#0x6c]`/`#0x6e`) and the impact and blast (FUN_0206E450,
// FUN_0206E60C, `ldrh [bp,#0x70]`/`#0x72`) read their own u16 pair; vanilla
// gives the two the same values. The flags are read every flight tick by the
// contact test (FUN_02054438) and the blocking test (FUN_02053F90), the speed
// once per shot (Entity::virtual_02 hands a non-unit bp+0x0C to its seeker).
// Left out: +0x14 and +0x15 (what follows a landing, the flight model: other
// values leave a shot alive or still), +0x65 (terrain class 1, on no map) and
// +0x6A (an event only spells use).
const BalField kAttackFields[] = {
    {"Hit damage min", 0x6C, 2, 0, 65535},
    {"Hit damage max", 0x6E, 2, 0, 65535},
    {"Impact damage min", 0x70, 2, 0, 65535},
    {"Impact damage max", 0x72, 2, 0, 65535},
    {"Speed", 0x0C, 4, 0, 0x7FFFFFFF},
    {"Hits buildings", 0x5E, 1, 0, 1},
    {"Hits flying", 0x5F, 1, 0, 1},
    {"Hits ground", 0x60, 1, 0, 1},
    {"Hits walls", 0x61, 1, 0, 1},
    {"Hurts allies", 0x62, 1, 0, 1},
    {"Hurts on the way", 0x63, 1, 0, 1},
    {"Stopped by cliffs", 0x64, 1, 0, 1},
    {"Stopped by buildings", 0x66, 1, 0, 1},
    {"Stopped by allies", 0x67, 1, 0, 1},
    {"Stopped by enemies", 0x68, 1, 0, 1},
    {"Stopped by walls", 0x69, 1, 0, 1},
    {"Explodes", 0x6B, 1, 0, 1},
    // docs/426: appended. Reader FUN_02053F90 (0x02053F90, line ~235) tests it
    // on the blueprint at [shot+0x160]+8: a shot over trees is not stopped.
    {"Over trees", 0x65, 1, 0, 1},
    // docs/438 (SG-0022): the animation set the shot is drawn with, an index
    // into the 18-byte-record table at 0x02127398 (FUN_0200CE1C). 0 draws
    // nothing; the table has 14 live sets (0..13) and the accessor would read
    // past it above that. Appended last, so stored indices keep their meaning.
    {"Sprite", 0x5D, 1, 0, 13},
};
// docs/416: values that are not in a blueprint but in the code, as one more
// record after the projectiles. Field 0 is a Gold Brick's worth: FUN_0205F038
// (a collectable's pickup) gives the hero's team `mov r5,#0x3E8` = 1000
// bricks, or `moveq r5,#0x96` = 150 when the session's +0x78 is 2. The patcher
// replaces it at the pickup (lb_patches.cpp); nothing is written to RAM.
const BalField kGlobalFields[] = {
    {"Gold Brick value", 0, 4, 0, 1000000},
};
constexpr int kGoldBrickStock = 1000;
constexpr int kUnitRecords = 182, kAttackRecords = 27;
constexpr int kGlobalRecord = kUnitRecords + kAttackRecords;   // 209
constexpr uint32_t kFirstRecord = 4u, kUnitSize = 0x7Cu, kAttackSize = 0x74u;
// docs/438 (SG-0022): four projectile records no unit fires and no code names
// (the only literal index lookups are record 202, ProjectileSpell, by the
// FireBall and ThunderHammer spells, so 202 is NOT spare). They are offered as
// "Spare projectile 1..4" and start as a copy of the Arrow, since two of them
// held nothing usable (204 has no sprite, 208 is all zero).
constexpr int kSpareRecords[4] = {203, 204, 205, 208};
constexpr int kSpareModel = 182;   // the Arrow
int spare_number(int rec) {
    for (int i = 0; i < 4; ++i)
        if (kSpareRecords[i] == rec) return i + 1;
    return 0;
}

struct Edit {
    int rec, field, value;
};
struct Written {
    uint32_t addr;
    uint8_t width;
    uint32_t before;
};

std::vector<Edit> g_live;          // the player's set (settings)
std::vector<Edit> g_play;          // a replay's set
bool g_play_on = false;
// docs/418: an online host's set, which a joiner runs in place of its own
// (with the host's pack and Same Builders), and the seed that names it.
std::vector<Edit> g_host;
bool g_host_on = false;
int g_host_slot = 0, g_host_builders = 0;
unsigned long long g_host_seed = 0ull;
std::vector<Written> g_written;    // what is in RAM now, to take it out
unsigned g_gen = 1u, g_written_gen = 0u;
unsigned g_live_gen = 1u;          // the player's set, for the recorder

int kind_of(int rec) {
    if (rec >= 0 && rec < kUnitRecords) return LB_BAL_UNITS;
    if (rec >= kUnitRecords && rec < kUnitRecords + kAttackRecords) return LB_BAL_ATTACKS;
    if (rec == kGlobalRecord) return LB_BAL_GLOBALS;   // docs/416
    return -1;
}

const BalField* field_of(int rec, int field) {
    const int k = kind_of(rec);
    if (k == LB_BAL_UNITS && field >= 0 &&
        field < (int)(sizeof kUnitFields / sizeof kUnitFields[0]))
        return &kUnitFields[field];
    if (k == LB_BAL_ATTACKS && field >= 0 &&
        field < (int)(sizeof kAttackFields / sizeof kAttackFields[0]))
        return &kAttackFields[field];
    if (k == LB_BAL_GLOBALS && field >= 0 &&
        field < (int)(sizeof kGlobalFields / sizeof kGlobalFields[0]))
        return &kGlobalFields[field];
    return nullptr;
}

// docs/416: a global's value as the game has it, before any edit.
int global_stock(int field) { return field == 0 ? kGoldBrickStock : -1; }

uint32_t record_at(uint32_t base, int rec) {
    if (rec < kUnitRecords) return base + kFirstRecord + (uint32_t)rec * kUnitSize;
    return base + kFirstRecord + (uint32_t)kUnitRecords * kUnitSize +
           (uint32_t)(rec - kUnitRecords) * kAttackSize;
}

uint32_t read_w(uint32_t a, int w) {
    return w == 1 ? bus_read_u8(a) : w == 2 ? bus_read_u16(a) : bus_read_u32(a);
}
void write_w(uint32_t a, int w, uint32_t v) {
    if (w == 1) bus_write_u8(a, (uint8_t)v);
    else if (w == 2) bus_write_u16(a, (uint16_t)v);
    else bus_write_u32(a, v);
}

bool guest_ram(uint32_t a) { return a >= 0x02000000u && a < 0x02400000u; }

std::vector<Edit>& active() {
    return g_play_on ? g_play : g_host_on ? g_host : g_live;
}

void put(std::vector<Edit>& set, int rec, int field, int value) {
    for (size_t i = 0; i < set.size(); ++i) {
        if (set[i].rec != rec || set[i].field != field) continue;
        if (value < 0) set.erase(set.begin() + (std::ptrdiff_t)i);
        else set[i].value = value;
        return;
    }
    if (value >= 0) set.push_back({rec, field, value});
}

// A structure's speed is the 0xFFFFFFFF sentinel, not a speed.
bool applies(uint32_t base, int rec, const BalField& f) {
    return !(f.width == 4 && read_w(record_at(base, rec) + f.off, 4) == 0xFFFFFFFFu);
}

}  // namespace

extern "C" int lb_balance_field_count(int kind) {
    return kind == LB_BAL_UNITS ? (int)(sizeof kUnitFields / sizeof kUnitFields[0])
         : kind == LB_BAL_ATTACKS ? (int)(sizeof kAttackFields / sizeof kAttackFields[0])
         : kind == LB_BAL_GLOBALS ? (int)(sizeof kGlobalFields / sizeof kGlobalFields[0])
         : 0;
}

// docs/416: a global's value for the game now -- the replay's or the player's
// set -- or -1 for the game's own. Offline only, like every value here.
extern "C" int lb_balance_global(int field) {
    // docs/418: online, the host's set (a host's own is this machine's).
    const int net = lb_net_guest_state();
    const bool hosting = net == 10 || net == 2 || net == 3 || net == 4 || net == 11;
    if (lb_balance_custom_blocked() && !g_host_on && !hosting) return -1;
    for (const Edit& e : active())
        if (e.rec == kGlobalRecord && e.field == field) return e.value;
    return -1;
}
extern "C" const char* lb_balance_field_name(int kind, int field) {
    const int first = lb_balance_record_first(kind);
    const BalField* f = field_of(first, field);
    return f ? f->name : "";
}
extern "C" int lb_balance_field_max(int kind, int field) {
    const BalField* f = field_of(lb_balance_record_first(kind), field);
    return f ? f->max : 0;
}
extern "C" int lb_balance_record_first(int kind) {
    return kind == LB_BAL_ATTACKS ? kUnitRecords
         : kind == LB_BAL_GLOBALS ? kGlobalRecord : 0;
}
extern "C" int lb_balance_record_count(int kind) {
    return kind == LB_BAL_ATTACKS ? kAttackRecords
         : kind == LB_BAL_UNITS ? kUnitRecords
         : kind == LB_BAL_GLOBALS ? 1 : 0;
}

// The record's own name, from the string the loader pointed +0x00 at.
extern "C" int lb_balance_record_name(int rec, char* out, int cap) {
    if (!out || cap <= 0) return 0;
    out[0] = 0;
    if (kind_of(rec) == LB_BAL_GLOBALS)   // docs/416
        return std::snprintf(out, (size_t)cap, "%s", "Pickups");
    if (const int sp = spare_number(rec))   // docs/438
        return std::snprintf(out, (size_t)cap, "Spare projectile %d", sp);
    const uint32_t base = lb_patches_blueprint_base();
    if (!base || kind_of(rec) < 0) return 0;
    const uint32_t s = bus_read_u32(record_at(base, rec));
    if (!guest_ram(s)) return 0;
    int n = 0;
    for (; n < cap - 1; ++n) {
        const uint8_t c = bus_read_u8(s + (uint32_t)n);
        if (!c || c < 0x20 || c > 0x7E) break;
        out[n] = (char)c;
    }
    out[n] = 0;
    return n;
}
extern "C" int lb_balance_record_category(int rec) {
    const uint32_t base = lb_patches_blueprint_base();
    if (!base || kind_of(rec) != LB_BAL_UNITS) return -1;
    return bus_read_u8(record_at(base, rec) + 0x5Cu);
}
extern "C" int lb_balance_record_projectile(int rec) {
    const uint32_t base = lb_patches_blueprint_base();
    if (!base || kind_of(rec) != LB_BAL_UNITS) return -1;
    const int p = bus_read_u16(record_at(base, rec) + 0x66u);
    return (p >= kUnitRecords && p < kUnitRecords + kAttackRecords) ? p : -1;
}

extern "C" int lb_balance_value(int rec, int field) {
    if (kind_of(rec) == LB_BAL_GLOBALS) {   // docs/416: the code's, or the set's
        if (!field_of(rec, field)) return -1;
        for (const Edit& e : active())
            if (e.rec == rec && e.field == field) return e.value;
        return global_stock(field);
    }
    const uint32_t base = lb_patches_blueprint_base();
    const BalField* f = field_of(rec, field);
    if (!base || !f || !applies(base, rec, *f)) return -1;
    return (int)read_w(record_at(base, rec) + f->off, f->width);
}
extern "C" int lb_balance_base(int rec, int field) {
    if (kind_of(rec) == LB_BAL_GLOBALS) return global_stock(field);   // docs/416
    const uint32_t base = lb_patches_blueprint_base();
    const BalField* f = field_of(rec, field);
    if (!base || !f) return -1;
    const uint32_t a = record_at(base, rec) + f->off;
    // docs/438: newest first -- a spare projectile's starting copy is written
    // before the player's value, which is what sits beneath it.
    for (size_t i = g_written.size(); i-- > 0;)
        if (g_written[i].addr == a && g_written[i].width == f->width)
            return (int)g_written[i].before;
    return lb_balance_value(rec, field);
}

extern "C" int lb_balance_custom_get(int rec, int field) {
    for (const Edit& e : g_live)
        if (e.rec == rec && e.field == field) return e.value;
    return -1;
}
extern "C" void lb_balance_custom_set(int rec, int field, int value) {
    const BalField* f = field_of(rec, field);
    if (!f) return;
    if (value > f->max) value = f->max;
    put(g_live, rec, field, value);
    ++g_live_gen;
    if (!g_play_on) ++g_gen;
}
extern "C" void lb_balance_custom_clear_all(void) {
    g_live.clear();
    ++g_live_gen;
    if (!g_play_on) ++g_gen;
}
extern "C" int lb_balance_custom_size(void) { return (int)g_live.size(); }
// docs/418: any of the player's (or host's) values are in RAM now -- which,
// like a pack, can change the Imperial builder the patcher finds the block by.
extern "C" int lb_balance_custom_written(void) { return g_written.empty() ? 0 : 1; }
extern "C" unsigned lb_balance_custom_generation(void) { return g_live_gen; }

extern "C" int lb_balance_custom_text(char* out, int cap) {
    if (!out || cap <= 0) return 0;
    int n = 0;
    out[0] = 0;
    for (const Edit& e : g_live) {
        const int w = std::snprintf(out + n, (size_t)(cap - n), "%s%d:%d=%d",
                                    n ? "," : "", e.rec, e.field, e.value);
        if (w < 0 || n + w >= cap) break;
        n += w;
    }
    return n;
}

namespace {
void parse_into(std::vector<Edit>& set, const char* text) {
    set.clear();
    for (const char* p = text; p && *p;) {
        int rec = -1, field = -1, value = -1, used = 0;
        if (std::sscanf(p, "%d:%d=%d%n", &rec, &field, &value, &used) == 3 &&
            used > 0) {
            if (field_of(rec, field) && value >= 0) put(set, rec, field, value);
            p += used;
        } else {
            ++p;
        }
        while (*p == ',' || *p == ' ') ++p;
    }
}
}  // namespace

extern "C" int lb_balance_custom_parse(const char* text) {
    parse_into(g_live, text);
    ++g_live_gen;
    if (!g_play_on) ++g_gen;
    return (int)g_live.size();
}

// ── docs/426: IMPORT FROM A ROM OR AN Entities.ebp ─────────────────────────
//
// The file's blueprint is diffed against the player's own ROM's, record by
// record. Every field whose bytes differ becomes a custom value (on Vanilla:
// the caller sets the pack); a differing byte that no field covers is counted
// and left alone, so nothing invisible changes.
bool lb_mods_blueprint_file(const char* path, std::vector<uint8_t>* out,
                            std::string* why);   // lb_mods.cpp
bool lb_mods_blueprint_own(std::vector<uint8_t>* out);

extern "C" int lb_balance_import_file(const char* path, char* msg, int msg_cap) {
    auto say = [&](const std::string& s) {
        if (msg && msg_cap > 0) std::snprintf(msg, (size_t)msg_cap, "%s", s.c_str());
    };
    std::string why;
    std::vector<uint8_t> mod, van;
    if (!lb_mods_blueprint_file(path, &mod, &why)) { say(why); return -1; }
    if (!lb_mods_blueprint_own(&van)) {
        say("the game's own blueprint is not available yet (is a ROM loaded?)");
        return -1;
    }
    if (mod.size() != van.size()) {
        say("that blueprint is a different size (" + std::to_string(mod.size()) +
            " bytes, the game's is " + std::to_string(van.size()) + ")");
        return -1;
    }
    g_live.clear();
    int values = 0, outside = 0;
    std::vector<int> per_field_units(64, 0), per_field_attacks(64, 0);
    const uint32_t records_end = kFirstRecord + (uint32_t)kUnitRecords * kUnitSize +
                                 (uint32_t)kAttackRecords * kAttackSize;
    for (uint32_t i = 0; i < mod.size(); ++i)
        if (i >= records_end && mod[i] != van[i]) ++outside;
    for (int rec = 0; rec < kUnitRecords + kAttackRecords; ++rec) {
        const uint32_t at = rec < kUnitRecords
            ? kFirstRecord + (uint32_t)rec * kUnitSize
            : kFirstRecord + (uint32_t)kUnitRecords * kUnitSize +
                  (uint32_t)(rec - kUnitRecords) * kAttackSize;
        const uint32_t size = rec < kUnitRecords ? kUnitSize : kAttackSize;
        bool covered[0x80] = {false};
        const int nf = lb_balance_field_count(kind_of(rec));
        for (int fi = 0; fi < nf; ++fi) {
            const BalField* f = field_of(rec, fi);
            if (!f) continue;
            uint32_t a = 0u, b = 0u;
            for (int k = 0; k < f->width; ++k) {
                covered[f->off + k] = true;
                a |= (uint32_t)van[at + f->off + (uint32_t)k] << (8 * k);
                b |= (uint32_t)mod[at + f->off + (uint32_t)k] << (8 * k);
            }
            if (a == b) continue;
            if (b > (uint32_t)f->max) {   // a value the menu cannot hold
                for (int k = 0; k < f->width; ++k)
                    if (van[at + f->off + (uint32_t)k] != mod[at + f->off + (uint32_t)k])
                        ++outside;
                continue;
            }
            put(g_live, rec, fi, (int)b);
            ++values;
            (rec < kUnitRecords ? per_field_units : per_field_attacks)[(size_t)fi]++;
        }
        for (uint32_t o = 0; o < size; ++o)
            if (!covered[o] && van[at + o] != mod[at + o]) ++outside;
    }
    int fields = 0;
    for (int n : per_field_units) fields += n ? 1 : 0;
    for (int n : per_field_attacks) fields += n ? 1 : 0;
    ++g_live_gen;
    if (!g_play_on) ++g_gen;
    const char* base = path;
    for (const char* p = path; *p; ++p)
        if (*p == '/' || *p == '\\') base = p + 1;
    std::fprintf(stderr, "[lb_balance] imported %s: %d values in %d fields, %d bytes "
                 "outside the menu\n", base, values, fields, outside);
    for (int fi = 0; fi < 64; ++fi) {
        if (per_field_units[(size_t)fi])
            std::fprintf(stderr, "[lb_balance]   unit %-18s %3d record(s)\n",
                         kUnitFields[fi].name, per_field_units[(size_t)fi]);
        if (per_field_attacks[(size_t)fi])
            std::fprintf(stderr, "[lb_balance]   attack %-16s %3d record(s)\n",
                         kAttackFields[fi].name, per_field_attacks[(size_t)fi]);
    }
    std::fflush(stderr);
    say("Imported " + std::to_string(values) + " value(s) in " +
        std::to_string(fields) + " field(s) from " + base + "; " +
        std::to_string(outside) + " byte(s) outside the menu were left alone.");
    return values;
}

extern "C" int lb_balance_custom_dirty(void) { return g_gen != g_written_gen ? 1 : 0; }

extern "C" void lb_balance_custom_revert(unsigned int base) {
    for (size_t i = g_written.size(); i-- > 0;)
        write_w(g_written[i].addr, g_written[i].width, g_written[i].before);
    g_written.clear();
    g_written_gen = 0u;
    (void)base;
}

extern "C" int lb_balance_custom_apply(unsigned int base) {
    lb_balance_custom_revert(base);
    if (!base) return 0;
    // docs/438: the spare projectiles start as the Arrow as the pack leaves
    // it (written first, kept in g_written, so the revert above takes them
    // out too). Every machine does this, so the sim agrees online.
    {
        const uint32_t model = record_at(base, kSpareModel);
        for (const int rec : kSpareRecords) {
            const uint32_t r = record_at(base, rec);
            // The speed (+0x0C..0x0F) and the sprite, flags and damages
            // (+0x5C..0x73), byte by byte so a field's "before" stays its own.
            for (uint32_t o = 0u; o < kAttackSize; ++o) {
                if (!((o >= 0x0Cu && o < 0x10u) || o >= 0x5Cu)) continue;
                const uint8_t want = bus_read_u8(model + o);
                if (bus_read_u8(r + o) == want) continue;
                g_written.push_back({r + o, 1, bus_read_u8(r + o)});
                bus_write_u8(r + o, want);
            }
        }
    }
    // docs/426 test aid: LB_BALANCE_IMPORT=<.nds or Entities.ebp> imports once.
    static bool env_done = false;
    if (!env_done) {
        env_done = true;
        if (const char* path = std::getenv("LB_BALANCE_IMPORT")) {
            char msg[256];
            lb_balance_import_file(path, msg, (int)sizeof msg);
        }
    }
    int n = 0;
    for (const Edit& e : active()) {
        if (kind_of(e.rec) == LB_BAL_GLOBALS) continue;   // docs/416: not in RAM
        const BalField* f = field_of(e.rec, e.field);
        if (!f || !applies(base, e.rec, *f)) continue;
        const uint32_t r = record_at(base, e.rec);
        const uint16_t offs[2] = {f->off, f->mirror};
        for (const uint16_t off : offs) {
            if (!off) continue;
            const uint32_t a = r + off;
            g_written.push_back({a, f->width, read_w(a, f->width)});
            write_w(a, f->width, (uint32_t)e.value);
        }
        ++n;
    }
    g_written_gen = g_gen;
    if (n)
        std::fprintf(stderr, "[lb_balance] %d value(s) of the %s set written\n",
                     n, g_play_on ? "recording's" : g_host_on ? "host's" : "player's");
    return n;
}

// docs/396: a reset reloads the blueprints, so nothing is written any more.
extern "C" void lb_balance_custom_on_reset(void) {
    g_written.clear();
    g_written_gen = 0u;
}

extern "C" void lb_balance_custom_play_begin(const char* text) {
    parse_into(g_play, text);
    g_play_on = true;
    ++g_gen;
}
extern "C" void lb_balance_custom_play_set(int rec, int field, int value) {
    if (!g_play_on || !field_of(rec, field)) return;
    put(g_play, rec, field, value);
    ++g_gen;
}
extern "C" void lb_balance_custom_play_end(void) {
    if (!g_play_on) return;
    g_play_on = false;
    g_play.clear();
    ++g_gen;
}

// ── docs/418: THE HOST'S BALANCE, ONLINE ───────────────────────────────────
//
// Every machine in a match must run one rule set. A host's set is its pack,
// its Same Builders source and its own values; it travels to the joiners
// with the host's rules (lb_teams.cpp), named by a SEED: FNV-1a 64 over the
// pack, the builders and the values in (record, field) order. A joiner runs
// the set it received in place of its own -- the pack and builders through
// the patcher (lb_patches.cpp), the values as the active set here -- and
// cannot ready until it is in force; leaving the lobby gives it its own back.

namespace {
unsigned long long seed_of(int slot, int builders, std::vector<Edit> set) {
    std::sort(set.begin(), set.end(), [](const Edit& a, const Edit& b) {
        return a.rec != b.rec ? a.rec < b.rec : a.field < b.field;
    });
    unsigned long long h = 0xCBF29CE484222325ull;
    auto mix = [&](uint32_t v) {
        for (int i = 0; i < 4; ++i) {
            h ^= (v >> (8 * i)) & 0xFFu;
            h *= 0x100000001B3ull;
        }
    };
    mix((uint32_t)slot);
    mix((uint32_t)builders);
    for (const Edit& e : set) {
        mix((uint32_t)e.rec);
        mix((uint32_t)e.field);
        mix((uint32_t)e.value);
    }
    return h;
}
}  // namespace

// This machine's own set, for a host to send: its seed, and the values in
// (record, field) order.
extern "C" unsigned long long lb_balance_local_seed(int slot, int builders) {
    return seed_of(slot, builders, g_live);
}
extern "C" int lb_balance_local_values(int* triples, int max) {
    std::vector<Edit> s = g_live;
    std::sort(s.begin(), s.end(), [](const Edit& a, const Edit& b) {
        return a.rec != b.rec ? a.rec < b.rec : a.field < b.field;
    });
    int n = 0;
    for (const Edit& e : s) {
        if (n >= max) break;
        triples[3 * n] = e.rec;
        triples[3 * n + 1] = e.field;
        triples[3 * n + 2] = e.value;
        ++n;
    }
    return (int)s.size();
}

// A joiner's: the host's set, complete. Returns 1 when its seed checks out
// (and it is now the active set), 0 when it does not (and nothing changed).
extern "C" int lb_balance_host_set(unsigned long long seed, int slot, int builders,
                                   const int* triples, int n) {
    std::vector<Edit> s;
    for (int i = 0; i < n; ++i) {
        const int rec = triples[3 * i], field = triples[3 * i + 1];
        const int value = triples[3 * i + 2];
        if (field_of(rec, field) && value >= 0) put(s, rec, field, value);
    }
    // Seed 0 is an older host's: no balance sent, so the game's own.
    if (seed != 0ull && seed_of(slot, builders, s) != seed) return 0;
    if (g_host_on && g_host_seed == seed) return 1;
    g_host = std::move(s);
    g_host_slot = slot;
    g_host_builders = builders;
    g_host_seed = seed;
    g_host_on = true;
    ++g_gen;
    std::fprintf(stderr, "[lb_balance] the host's balance: pack %d, builders %d, "
                 "%zu value(s), seed %016llX\n", slot, builders, g_host.size(), seed);
    return 1;
}
extern "C" void lb_balance_host_clear(void) {
    if (!g_host_on) return;
    g_host_on = false;
    g_host.clear();
    g_host_seed = 0ull;
    ++g_gen;
    std::fprintf(stderr, "[lb_balance] the host's balance is gone; this "
                 "machine's own is back\n");
}
extern "C" int lb_balance_host_on(void) { return g_host_on ? 1 : 0; }
extern "C" int lb_balance_host_slot(void) { return g_host_slot; }
extern "C" int lb_balance_host_builders(void) { return g_host_builders; }
extern "C" unsigned long long lb_balance_host_seed(void) { return g_host_seed; }
extern "C" int lb_balance_host_size(void) { return (int)g_host.size(); }

extern "C" const char* lb_balance_custom_blocked(void) {
    const int net = lb_net_guest_state();
    if (net != 0 && net != -1)
        return "not while hosting, in a lobby or online: both players must "
               "play by the same numbers";
    return nullptr;
}
